#include "stdafx.h"#include "HcdElementBase.h"struct SSTRIG_P{#include "PrivateVars/STRIG.h"};class KSTRIG : public KHcdElementBase  , protected SSTRIG_P{  enum ETriggerType  {    OfftoOn,    OntoOff,    Both,  }tt;public:  static IHcdElement *Create();protected:  static void InitParm();  virtual void OnCreated( int domain, LPCSTR pszHmiTagName );  virtual void OnFilledProjectSettings();  virtual void StepCalc( SStepCalcParams &params );};static KHcdFactory _STRIG("STRIG", KSTRIG::Create);IHcdElement *KSTRIG::Create(){  return new KSTRIG;}//////////////////////////////////////////////////////////////////////////#include "_InitInfo.h"DECLARE_PRIVATE_VARSINFO( KSTRIG, 5 )void KSTRIG::InitParm(){#include "PrivateVars/STRIG.h"  qsort( s_privateVarInfo, s_kprivateVarInfo, sizeof( SVarInfo ), CompVarInfo );}void KSTRIG::OnCreated( int domain, LPCSTR pszHmiTagName ){  if( !s_kprivateVarInfo )    InitParm();  m_kPrivateVarsInfo = s_kprivateVarInfo;  m_pPrivateVarsInfo = s_privateVarInfo;  m_pPrivateObject = (BYTE*)this;}void KSTRIG::OnFilledProjectSettings(){  if( !strcmp(TT,"OFF to ON") )    tt = OfftoOn;  else if( !strcmp(TT,"ON to OFF") )    tt = OntoOff;  else if( !strcmp(TT,"Both") )    tt = Both;  else  {    ASSD( 0 );  }}void KSTRIG::StepCalc( SStepCalcParams &params ){  switch( tt )  {  case OfftoOn:    if( !prevIn && IN )      OUT = 1;    else      OUT = 0;    break;  case OntoOff:    if( prevIn && !IN )      OUT = 1;    else      OUT = 0;    break;  case Both:    if( prevIn != IN )      OUT = 1;    else      OUT = 0;    break;  }  prevIn = IN;}